import {train,parseData} from './statistics.mjs';
import {validateControl} from './physics.mjs';
export function clearEvidence(s,data=false){s.report='';s.opt=null;s.pick=null;s.refined=null;if(data){s.fit=null;s.pred=[];}}
export function updateParameter(s,group,key,value){if(!['p','c'].includes(group)||!Number.isFinite(value))throw Error('参数无效');const next={...s[group],[key]:value};const errors=validateControl(group==='p'?next:s.p,group==='c'?next:s.c);if(errors.length)throw Error(errors.join('；'));s[group]=next;clearEvidence(s);}
export function fitState(s){const fitted=train(s.rows,{ratios:s.ratios},Object.keys(s.partitions).length?s.partitions:null);if(Object.keys(s.partitions).length){const active=parseData([...s.partitions.train,...s.partitions.validation,...s.partitions.test]);s.rows=active;s.all=active;s.source='upload';}s.fit=fitted;s.model=fitted.best;s.report='';return fitted;}
export const chatPayload=(question,report)=>({question,evidence:{calculation_report:report,scope:'油藏孪生措施研究情景；非现场执行记录'}});
export function applyGeology(s,data){if(!data||typeof data.source!=='string'||!data.source.trim())throw Error('地质参数须标明source来源');const allowed=['phi','volume','ct','swc','sor','Bo','Bw','muo','muw','J','injJ','gor','depth','eta','fracture'];const p={...s.p};let count=0;for(const k of allowed)if(data[k]!==undefined){if(typeof data[k]!=='number'||!Number.isFinite(data[k]))throw Error('地质参数须为数值');p[k]=data[k];count++;}if(!count)throw Error('未提供可用地质参数');const errors=validateControl(p,s.c);if(errors.length)throw Error(errors.join('；'));s.p=p;s.geoSource=data.source;clearEvidence(s);}
export function applyMonitoring(s,data){if(!Array.isArray(data)||!data.length||data.length>1000)throw Error('监测数据须为1—1000条JSON数组');const rows=data.map(r=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date||typeof r.reservoir_pressure!=='number'||!Number.isFinite(r.reservoir_pressure)||!r.source||typeof r.source!=='string'||r.sw!==undefined&&(typeof r.sw!=='number'||!Number.isFinite(r.sw)||r.sw<0||r.sw>1))throw Error('监测须含有效date、reservoir_pressure、source，可选sw；井筒pressure不能代替地层平均压力');return {...r};}).sort((a,b)=>a.date.localeCompare(b.date));if(new Set(rows.map(r=>r.date)).size!==rows.length)throw Error('监测日期不可重复');const last=rows.at(-1),p={...s.p,p:last.reservoir_pressure,sw:last.sw??s.p.sw},errors=validateControl(p,s.c);if(errors.length)throw Error(errors.join('；'));s.p=p;s.monitor=rows;clearEvidence(s);}
